export type ResearchSource = { label: string; href: string };

export type DeepResearch = {
  context: string;
  tools: string[];
  sections: { heading: string; body: string; bullets: string[] }[];
  sources: ResearchSource[];
  faq: [string, string][];
};

const source = (label: string, href: string): ResearchSource => ({ label, href });

export const deepResearch: Record<string, DeepResearch> = {
  "best-mcp-observability-platforms": {
    context: "The current market is splitting into MCP-specific server telemetry, general application monitoring, agent tracing, and infrastructure observability. Sentry now documents MCP server monitoring with per-tool request count, error rate, duration, and p95 views. Grafana documents MCP metrics, traces, and logs through Prometheus, Tempo, and Loki. Langfuse documents linked client and server traces through the MCP _meta field. These are useful products, but they answer different questions. A serious buyer's guide must compare evidence boundaries, not just feature names.",
    tools: ["TrackMCP", "Sentry MCP monitoring", "Grafana MCP observability", "Datadog MCP Server", "Langfuse MCP tracing", "OpenTelemetry MCP semantic conventions"],
    sections: [
      { heading: "What to verify in a live evaluation", body: "Give every candidate the same server and the same five fixtures: a healthy call, an application error inside a successful transport response, a slow dependency, a catalog change, and an explicit workflow completion event. Ask the product to show the first broken event, the affected client and tool, the release, and the evidence timestamp. If a product only shows an HTTP request or a model span, record that as a boundary limitation rather than treating it as full MCP coverage.", bullets: ["Run a real TypeScript or Python server through the production transport.", "Test both stdio and Streamable HTTP where the product claims support.", "Verify redaction before ingestion, not only masking in a dashboard.", "Check export, deletion, retention, and failure behavior before procurement."] },
      { heading: "How TrackMCP fits without claiming to replace everything", body: "TrackMCP is strongest when the unanswered question is what happened at the MCP server boundary: which client connected, what catalog it saw, which tool ran, what result came back, how long it took, and whether the application emitted an outcome. It should be positioned alongside, not as a universal replacement for, Sentry errors, Grafana infrastructure, Datadog APM, or Langfuse agent traces. That honest positioning is more useful to technical buyers and more defensible in search content.", bullets: ["Use TrackMCP for server-boundary adoption and reliability.", "Use Sentry for exceptions and issue workflows when it is already the system of record.", "Use Grafana or Datadog for infrastructure, logs, and broad service health.", "Use Langfuse for agent and model traces when host-side context is required."] },
    ],
    sources: [source("Sentry MCP server monitoring", "https://sentry.io/cookbook/monitor-mcp-server/"), source("Grafana MCP observability", "https://grafana.com/docs/grafana-cloud/ai-tools/mcp-servers/oss-mcp/developer/observability-metrics-and-tracing/"), source("Langfuse MCP tracing", "https://langfuse.com/docs/observability/features/mcp-tracing")],
    faq: [["Can one product provide every MCP observability signal?", "Usually not without tradeoffs. The server boundary, host agent, application, and infrastructure layers have different owners and evidence. Compare the join points and gaps instead of assuming a single dashboard proves the entire workflow."], ["Which tools belong in a shortlist?", "Start with products that can demonstrate your required boundary: TrackMCP for server-boundary analytics, Sentry for application errors, Grafana or Datadog for broader observability, and Langfuse for linked agent traces."]],
  },
  "mcp-observability-vs-llm-observability": {
    context: "MCP observability is often confused with LLM or agent observability because both contain tool calls. The distinction is operational. Langfuse shows how MCP clients and servers can produce separate traces and optionally link them by propagating W3C trace context in params._meta. OpenTelemetry's MCP conventions separately define client and server operations, sessions, methods, tools, transports, and opt-in arguments or results. A good article must explain the join, the missing context, and the privacy boundary.",
    tools: ["TrackMCP", "Langfuse", "OpenTelemetry GenAI semantic conventions", "Sentry AI Observability", "Datadog Agent Observability"],
    sections: [
      { heading: "The trace join is a contract, not magic", body: "A client-side span can be the parent of a server-side MCP span when the client injects traceparent and related context into the MCP request metadata and the server extracts it. That gives teams a linked view, but it does not make the server aware of the user's private prompt or the model's hidden reasoning. It also creates a trust and data-flow decision because metadata crosses the client/server boundary. Document who may inject, who may read, and how the context is redacted.", bullets: ["Keep client and server span ownership explicit.", "Use W3C context propagation only with a defined privacy policy.", "Treat missing or malformed context as an incomplete join, not as a failed request.", "Keep server evidence useful when no client trace is available."] },
      { heading: "Use one workflow query with separate measurements", body: "For an incident, show model time, client wait, MCP server time, dependency time, and final answer time as separate measurements. A server p95 can improve while end-to-end task latency gets worse because the model retries or the client spends more time selecting tools. TrackMCP can own the server-boundary slice and link outward when a host integration provides a safe correlation ID.", bullets: ["Do not add server calls, agent spans, and HTTP requests as separate user operations.", "Label whether a completion signal came from the application or was inferred.", "Keep prompts and tool payloads opt-in and bounded.", "Show missing spans and sampled segments in incident views."] },
    ],
    sources: [source("Langfuse MCP tracing", "https://langfuse.com/docs/observability/features/mcp-tracing"), source("OpenTelemetry MCP conventions", "https://github.com/open-telemetry/semantic-conventions-genai/blob/main/docs/gen-ai/mcp.md"), source("Datadog MCP client monitoring", "https://docs.datadoghq.com/llm_observability/guide/monitor_mcp_client/")],
    faq: [["Does a server trace prove what the model saw?", "No. It proves what the server received and returned. The host or client must provide model, prompt, retrieval, and selection context."], ["Should every team propagate trace context?", "Only after deciding the trust, privacy, and correlation contract. Propagation is valuable, but it should not silently export sensitive identifiers or prompts."]],
  },
  "mcp-server-monitoring-tools": {
    context: "The phrase MCP server monitoring covers several products and jobs. TrackMCP's browser tester performs bounded, read-only negotiation and catalog inspection. Sentry's MCP cookbook shows continuous server monitoring with most-used, slowest, and most-failing tool views. Grafana's MCP server exposes metrics for HTTP transports and traces and logs for any transport. These examples make the important distinction clear: a probe is a diagnostic snapshot, while production observability explains real traffic over time.",
    tools: ["TrackMCP MCP server tester", "TrackMCP server analytics", "Sentry", "Grafana and Tempo", "Datadog", "MCP Inspector"],
    sections: [
      { heading: "Build a layered monitoring policy", body: "Use a read-only probe before releases and when an endpoint is reported as unhealthy. Use continuous server-boundary telemetry for client mix, catalog exposure, tool calls, application errors, retries, latency, and outcomes. Use APM and infrastructure monitoring for process, host, database, and network causes. A single ping or one dashboard cannot cover all three layers.", bullets: ["Preflight: endpoint, auth challenge, protocol, capabilities, catalogs, pagination.", "Runtime: calls, results, errors, duration, retries, clients, releases.", "Infrastructure: process health, saturation, dependencies, logs, and network.", "Workflow: explicit completion, failure, cancellation, and unknown state."] },
      { heading: "Compare tools with failure fixtures", body: "A monitoring product should be tested against cases that fool naive dashboards. Return HTTP 200 with a tool result marked as an application error. Make only one dependency slow. Change one required schema field. Cause a client retry after a deadline. Then check whether the product identifies the affected tool and first broken event. This is a stronger evaluation than asking whether it has a latency chart.", bullets: ["Record the exact transport and SDK version.", "Keep test credentials disposable and side effects disabled.", "Verify error state survives sampling and export.", "Check that telemetry failure does not block the server."] },
    ],
    sources: [source("TrackMCP server tester", "https://trackmcp.com/tools/mcp-server-tester"), source("Sentry MCP monitoring", "https://sentry.io/cookbook/monitor-mcp-server/"), source("Grafana MCP observability", "https://grafana.com/docs/grafana-cloud/ai-tools/mcp-servers/oss-mcp/developer/observability-metrics-and-tracing/")],
    faq: [["Is MCP Inspector a replacement for monitoring?", "No. Inspector-style tools are useful for interactive development and diagnosis. Continuous monitoring needs real traffic, history, alerts, retention, and ownership."], ["What should alert first?", "Alert on sustained user-impacting result errors, negotiation failures, severe tail latency, auth rejection, catalog breakage, or workflow completion loss."]],
  },
  "mcp-server-monitoring-checklist": {
    context: "A checklist is only valuable when each item has an owner and an observable result. The official MCP conformance framework can run server scenarios and wire-schema checks, while the TrackMCP tester focuses on safe browser-direct discovery. Neither proves business correctness or every client workflow. The production checklist therefore needs protocol, application, security, and outcome layers.",
    tools: ["MCP Conformance Test Framework", "TrackMCP MCP server tester", "MCP Inspector", "Sentry", "Grafana", "OpenTelemetry"],
    sections: [
      { heading: "Turn each checklist item into evidence", body: "For each check, record the server release, protocol revision, transport, authentication mode, test client, and result artifact. “Catalog healthy” should link to a catalog snapshot or conformance result. “Telemetry safe” should link to a redaction fixture. “Workflow works” should link to a synthetic or real outcome event. This turns a readiness document into a repeatable release gate.", bullets: ["Preflight evidence: negotiation, capabilities, catalog, pagination, and auth.", "Contract evidence: schemas, validation, authorization, side effects, and errors.", "Runtime evidence: result state, latency, retries, cancellations, and outcomes.", "Governance evidence: owner, retention, deletion, runbook, and rollback."] },
      { heading: "Test the gaps between tools", body: "Run conformance for protocol requirements, a safe probe for endpoint behavior, contract tests for application semantics, and real telemetry for production behavior. A green conformance suite does not prove that a search tool returns correct data. A browser probe does not prove that a private client can authenticate. A dashboard does not prove that data was redacted before export.", bullets: ["Pin protocol revisions and record requirement sets.", "Keep application fixtures deterministic and side-effect safe.", "Run supported clients through the deployed transport.", "Make unknown, sampled, or incomplete evidence explicit."] },
    ],
    sources: [source("MCP conformance framework", "https://github.com/modelcontextprotocol/conformance"), source("TrackMCP health check", "https://trackmcp.com/tools/mcp-health-check"), source("MCP roadmap", "https://blog.modelcontextprotocol.io/posts/mcp-roadmap/")],
    faq: [["Does the official conformance suite certify production readiness?", "No. It checks scoped protocol requirements and wire behavior. Add application, authorization, side-effect, client compatibility, and workflow tests."], ["Who should sign the checklist?", "The server operator owns the release evidence. Security, platform, and product owners should sign the checks that cross their boundaries."]],
  },
  "mcp-observability-stack": {
    context: "A production stack should reflect the way MCP actually crosses systems. OpenTelemetry's MCP conventions define server and client spans, sessions, transports, methods, tools, and opt-in arguments and results. Grafana shows how those signals can flow to Prometheus, Tempo, and Loki. Langfuse shows linked agent and server traces. TrackMCP adds a product layer for server-boundary analytics and explicit outcomes. The stack is strongest when each layer has a clear owner.",
    tools: ["TrackMCP", "OpenTelemetry Collector", "Prometheus", "Grafana Tempo", "Grafana Loki", "Langfuse", "Sentry"],
    sections: [
      { heading: "Define source-of-truth ownership", body: "Choose one canonical source for each metric. Server tool duration belongs to the MCP server layer. Container CPU belongs to infrastructure. Model latency belongs to the agent layer. Workflow completion belongs to the application that can prove the outcome. Correlate the records, but do not sum them or publish multiple competing definitions of “success.”", bullets: ["Use stable non-secret correlation identifiers.", "Keep server, client, infrastructure, and business scopes labeled.", "Document sampling and missing-span behavior.", "Keep sensitive arguments and results opt-in."] },
      { heading: "Design for telemetry failure", body: "Telemetry is a dependency with its own queue, network path, exporter, retention, and access controls. Test what happens when ingestion is slow, unavailable, or returns an error. The MCP server should remain able to serve according to its reliability contract. An observability outage should create an evidence gap, not a new serving outage.", bullets: ["Bound queues and event sizes.", "Use asynchronous export with backpressure.", "Record dropped or sampled events as metadata.", "Alert on missing evidence separately from server errors."] },
    ],
    sources: [source("OpenTelemetry MCP conventions", "https://github.com/open-telemetry/semantic-conventions-genai/blob/main/docs/gen-ai/mcp.md"), source("Grafana MCP metrics and tracing", "https://grafana.com/docs/grafana-cloud/ai-tools/mcp-servers/oss-mcp/developer/observability-metrics-and-tracing/"), source("Langfuse MCP tracing", "https://langfuse.com/docs/observability/features/mcp-tracing")],
    faq: [["Can OpenTelemetry replace a product like TrackMCP?", "It can provide a common instrumentation and export foundation. A product still needs MCP-specific dashboards, analytics, retention, access, and workflow interpretation."], ["What is the first layer to add?", "Start at the boundary where your highest-risk question is answered. For an MCP server owner, that is usually connection, catalog, tool, result, latency, and outcome evidence."]],
  },
  "mcp-observability-open-source-vs-saas": {
    context: "Open source and SaaS are operating models, not quality labels. Grafana documents a flexible path using Prometheus, Tempo, Loki, and OpenTelemetry. Langfuse supports both Cloud and self-hosting. Sentry and Datadog provide managed systems with broader application and infrastructure features. TrackMCP is positioned around a focused MCP server-boundary workflow. The correct decision depends on data residency, maintenance capacity, query needs, and how quickly a team needs a useful incident view.",
    tools: ["TrackMCP", "Grafana OSS and Cloud", "Langfuse OSS and Cloud", "Sentry", "Datadog", "OpenTelemetry Collector"],
    sections: [
      { heading: "Price the operating burden", body: "For self-hosting, include storage, indexing, upgrades, backups, alerting, access control, schema migrations, on-call, and security review. For SaaS, include event volume, retention, seats, exports, vendor access, data residency, and the cost of a provider outage. Then add engineering time to instrument MCP semantics that a generic backend does not capture automatically.", bullets: ["Estimate calls, event size, dimensions, and retention.", "Count setup and ongoing maintenance hours.", "Test export, deletion, and incident access.", "Include the cost of an unanswered production question."] },
      { heading: "Run a same-workload proof", body: "Send the same redacted fixture through each candidate: a healthy call, 200-plus-application-error, slow dependency, catalog change, retry, and explicit outcome. Ask each system to answer who called, which tool failed, and whether the workflow completed. This exposes whether a low-cost generic stack actually provides the operational evidence your team needs.", bullets: ["Use identical payload and sampling policies.", "Measure time to first useful dashboard.", "Check support for stdio and Streamable HTTP.", "Document the missing fields rather than hiding them in a score."] },
    ],
    sources: [source("Grafana MCP observability", "https://grafana.com/docs/grafana-cloud/ai-tools/mcp-servers/oss-mcp/developer/observability-metrics-and-tracing/"), source("Langfuse deployment options", "https://langfuse.com/docs/observability/get-started"), source("TrackMCP security", "https://trackmcp.com/security")],
    faq: [["Is self-hosted always safer?", "No. Safety depends on collection, redaction, access, retention, patching, and deletion. Self-hosting gives control but also gives your team the operating responsibility."], ["Can a team use both SaaS and open source?", "Yes. Many teams keep regulated raw data in their own systems and send bounded operational metadata to a managed product."]],
  },
  "mcp-observability-pricing-cost": {
    context: "MCP observability cost grows through call volume, payload size, cardinality, retention, and engineering work. OpenTelemetry conventions make arguments and results opt-in, which is important for both cost and privacy. Sentry's MCP monitoring illustrates the product dimensions buyers expect, including per-tool request count, errors, duration, and p95. A cost guide should model those dimensions instead of comparing a single advertised plan.",
    tools: ["TrackMCP", "Sentry", "Datadog", "Grafana Cloud", "Langfuse", "OpenTelemetry Collector"],
    sections: [
      { heading: "Build a volume model", body: "Estimate servers, environments, clients, calls per day, average event size, high-cardinality dimensions, retention, and query frequency. Separate routine metadata from sampled payloads and incident captures. A catalog and client dimension can be more valuable than raw payloads, but it can also create expensive indexes when values are unbounded.", bullets: ["Events per server and tool.", "Average and tail event size.", "Indexed dimensions and cardinality.", "Retention, export, replay, and deletion requirements."] },
      { heading: "Include the price of missing evidence", body: "A cheap stack that cannot distinguish a 200-plus-tool error from a success may cost more during an incident than a focused product. Estimate time to install, time to query, time to build MCP-specific dashboards, and the cost of a failed release or unresolved customer report. Test the same incident query across candidates.", bullets: ["Setup and instrumentation effort.", "Maintenance and protocol upgrade effort.", "On-call investigation time.", "Cost of an incomplete or delayed diagnosis."] },
    ],
    sources: [source("OpenTelemetry MCP opt-in data fields", "https://github.com/open-telemetry/semantic-conventions-genai/blob/main/docs/gen-ai/mcp.md"), source("Sentry MCP monitoring", "https://sentry.io/cookbook/monitor-mcp-server/"), source("TrackMCP analytics", "https://trackmcp.com/mcp-server-analytics")],
    faq: [["Should I store every tool argument and result?", "No. Capture only what a defined diagnostic or product question needs. Bounded metadata often provides adoption and reliability evidence with less risk and cost."], ["How do I estimate growth?", "Model server count, calls, clients, tools, event size, and retention separately. New clients and tools can increase volume even when server count is flat."]],
  },
  "mcp-observability-for-python-servers": {
    context: "Python MCP teams need to reason about the process that actually serves requests, not only the interpreter that installed a package. The official Python SDK and common FastMCP deployments can use stdio or HTTP transports, while TrackMCP's Python integration focuses on additive server-boundary telemetry. Sentry documents Python MCP monitoring as another implementation path. A useful guide must cover virtual environments, workers, shutdown, redaction, and verification.",
    tools: ["TrackMCP Python SDK", "MCP Python SDK", "FastMCP", "Sentry Python SDK", "OpenTelemetry Python"],
    sections: [
      { heading: "Instrument the deployed process", body: "Put the wrapper around the server object that the deployment exports or runs. Verify the package resolves in the same virtual environment, container, or worker image that serves MCP. Then make a real tool call through the production-like transport. Import success is not ingestion success, and a shell variable is not proof that the worker received the key.", bullets: ["Check the production interpreter and lockfile.", "Use a stable service and environment name.", "Test worker startup and graceful shutdown.", "Verify the first event in the intended workspace."] },
      { heading: "Test Python-specific failure paths", body: "Exercise async cancellation, exception handling, dependency timeouts, process restart, and telemetry exporter failure. The wrapper should preserve tool schemas and results while keeping telemetry bounded and asynchronous. Capture an application error inside a successful MCP transport response so your tests do not rely on HTTP status alone.", bullets: ["Use deterministic fixtures with no customer data.", "Test a full or unavailable ingest queue.", "Keep tracebacks and arguments redacted.", "Measure instrumentation overhead separately from handler time."] },
    ],
    sources: [source("TrackMCP Python docs", "https://trackmcp.com/docs/python"), source("Sentry MCP monitoring", "https://sentry.io/cookbook/monitor-mcp-server/"), source("MCP Python SDK", "https://py.sdk.modelcontextprotocol.io/")],
    faq: [["Do I have to instrument every Python tool?", "A server-boundary wrapper can capture common protocol and tool signals. Add explicit events only for application outcomes the server can prove."], ["What is the most common missing-data cause?", "The key or package is present in a shell or build image, but not in the worker process that receives the MCP call."]],
  },
  "mcp-observability-for-typescript-servers": {
    context: "TypeScript MCP deployments often have a server instance, transport, router, proxy, and worker boundary spread across modules. The official TypeScript SDK, Sentry's Node MCP monitoring, and TrackMCP's TypeScript wrapper all make the integration point important. The article should show why wrapping a test server or a pre-registration object creates false confidence, and why release and transport verification matter.",
    tools: ["TrackMCP TypeScript SDK", "MCP TypeScript SDK", "Sentry Node SDK", "OpenTelemetry JS", "Grafana Tempo"],
    sections: [
      { heading: "Wrap the object that production serves", body: "Register tools and schemas first, then wrap the server instance that receives the production transport. If a framework creates a new instance per request, verify whether the SDK supports that lifecycle and where session context is preserved. Test through the same proxy, auth, and deployment mode used by real clients.", bullets: ["Keep service, environment, and release identifiers stable.", "Test Streamable HTTP and stdio separately where supported.", "Verify catalog and tool response equality before and after wrapping.", "Check graceful shutdown and exporter backpressure."] },
      { heading: "Use a regression fixture, not a screenshot", body: "A dashboard screenshot does not prove that instrumentation preserved semantics. Assert that a known tool call returns the same result, that an application error remains visible, that latency dimensions are recorded, and that telemetry failure does not block the event loop. Record the Node, SDK, transport, and build versions with the result.", bullets: ["Test cold start and restart.", "Test a slow dependency and a canceled request.", "Keep arguments and results opt-in and redacted.", "Compare p95 before and after instrumentation."] },
    ],
    sources: [source("TrackMCP TypeScript docs", "https://trackmcp.com/docs/typescript"), source("Sentry MCP monitoring", "https://sentry.io/cookbook/monitor-mcp-server/"), source("MCP TypeScript SDK", "https://ts.sdk.modelcontextprotocol.io/")],
    faq: [["Will a wrapper change my tool contract?", "It should be additive, but verify schemas and responses with contract tests. The serving instance and transport lifecycle still need to be tested."], ["Can generic OpenTelemetry replace the wrapper?", "It can export useful spans, but MCP-specific catalog, result, retry, client, and outcome fields still need deliberate instrumentation."]],
  },
  "mcp-observability-remote-http": {
    context: "Remote MCP failures cross more boundaries than local stdio failures. The client, DNS, TLS, edge, gateway, protected-resource metadata, authorization server, MCP transport, server process, and downstream dependency can each produce a different symptom. The MCP authorization guidance requires a 401 challenge and protected-resource metadata for discovery. TrackMCP's browser-direct tester deliberately limits itself to safe, read-only HTTPS inspection, while runtime analytics observes authorized traffic that reaches the server.",
    tools: ["TrackMCP MCP health check", "TrackMCP MCP server tester", "MCP Inspector", "Grafana", "Sentry", "Datadog"],
    sections: [
      { heading: "Name every hop in the path", body: "For a remote incident, record endpoint, TLS, gateway, authorization challenge, protected-resource metadata, token audience, protocol revision, catalog, tool, and dependency. Measure gateway wait and server duration separately. A CORS failure is browser evidence, not proof that the endpoint is down. A 401 can be a healthy authentication discovery step or an invalid resource indicator, depending on the headers and metadata.", bullets: ["Keep the canonical resource URL stable.", "Validate audience and resource indicators.", "Record auth outcomes without bearer tokens.", "Preserve a safe correlation ID across hops."] },
      { heading: "Use probes and runtime signals together", body: "A bounded probe can negotiate and inspect catalogs without executing tools. It cannot prove a private client's scope, downstream data, or workflow completion. Runtime telemetry shows what authorized clients actually did. Keep the probe's verdict dimensions separate from the production error budget so a browser policy issue does not page the server team as an outage.", bullets: ["Reject private, metadata, local, and credential-bearing targets.", "Bound response bodies, pagination, and total duration.", "Report authentication, CORS, protocol, catalog, and latency findings separately.", "Run the probe after gateway, auth, and SDK changes."] },
    ],
    sources: [source("TrackMCP MCP server tester", "https://trackmcp.com/tools/mcp-server-tester"), source("MCP Apps authorization guidance", "https://apps.extensions.modelcontextprotocol.io/api/documents/authorization.html"), source("TrackMCP remote observability", "https://trackmcp.com/mcp-observability/remote-http")],
    faq: [["Does a browser CORS failure prove downtime?", "No. It proves that the browser could not expose a usable response. Test from an authorized client or server-side path before declaring the endpoint unavailable."], ["Should a generic remote probe execute tools?", "No. Keep generic probes read-only. Use an explicit synthetic transaction only when its side effects and credentials are controlled."]],
  },
  "mcp-observability-multi-server": {
    context: "A fleet of MCP servers needs more than a global request count. The official registry, Glama, Smithery, and TrackMCP's own repository can help discover or catalog servers, but declared inventory is not proof of live behavior. Fleet observability must join server identity, owner, environment, release, client, catalog, tool, reliability, and outcome evidence while preserving per-server namespaces.",
    tools: ["TrackMCP", "Official MCP Registry", "Glama", "Smithery", "Grafana", "OpenTelemetry Collector"],
    sections: [
      { heading: "Keep discovery and runtime evidence separate", body: "A registry record tells you that a server was declared or published. A live probe tells you what an endpoint exposes at a point in time. Runtime telemetry tells you what authorized clients actually called. Store all three states with source and verification timestamps. This prevents a stale directory entry from becoming a false production inventory.", bullets: ["Declared, discovered, tested, and approved are different states.", "Store owner, environment, release, and canonical endpoint.", "Preserve catalog version and access policy provenance.", "Keep unknown ownership visible instead of silently assigning it."] },
      { heading: "Aggregate without collapsing identity", body: "Fleet charts should aggregate error, latency, client, catalog, and outcome signals, but every point must drill back to the exact server, tool, release, and owner. A tool called search_docs on two servers is not one global tool. Namespace metrics by server identity and keep a stable identity across deployments and regions.", bullets: ["Use server and environment as required dimensions.", "Compare releases before and after rollout.", "Route alerts to an accountable owner.", "Retire keys, telemetry, and catalog entries with the server lifecycle."] },
    ],
    sources: [source("Official MCP Registry", "https://registry.modelcontextprotocol.io/"), source("Glama MCP directory API", "https://glama.ai/mcp/reference"), source("TrackMCP server analytics", "https://trackmcp.com/mcp-server-analytics")],
    faq: [["Can a registry provide observability?", "It can provide discovery metadata and publisher information. It cannot prove that a live endpoint still exposes the same catalog or that its tools are reliable."], ["How do I avoid cross-server tool collisions?", "Namespace every metric and permission by server identity. A local tool name is not globally unique in a host or fleet."]],
  },
  "mcp-observability-privacy-redaction": {
    context: "OpenTelemetry's MCP conventions mark tool arguments and results as opt-in, which is a useful baseline for privacy-aware design. MCP Apps documentation also emphasizes sandboxed views, restrictive CSP, and explicit network domains. A serious MCP telemetry article must treat collection, redaction, access, retention, export, and deletion as separate controls. TrackMCP's server-boundary model is relevant because redaction can happen in the serving process before telemetry leaves it.",
    tools: ["TrackMCP redaction", "OpenTelemetry MCP conventions", "Sentry data scrubbing", "Datadog sensitive data scanner", "Grafana access controls", "MCP Apps CSP"],
    sections: [
      { heading: "Classify before you instrument", body: "For each tool, decide whether the diagnostic needs the raw value, a type, a length, a category, a hash, or nothing. Customer records, credentials, prompts, documents, authorization headers, and error traces should not become default telemetry. Redact before queues, logs, exporters, or support snapshots receive the value. Dashboard masking is too late for a leaked event.", bullets: ["Use metadata mode for sensitive tools.", "Keep bearer tokens and authorization codes out of labels.", "Treat stack traces and error messages as data sources.", "Fail closed when a new unclassified field appears."] },
      { heading: "Prove the policy with hostile fixtures", body: "Create fixtures with nested secrets, long values, repeated fields, malicious strings, and errors containing identifiers. Run success, validation failure, dependency failure, retry, cancellation, and shutdown paths. Inspect process logs, queues, exports, indexes, and dashboards. A privacy test is complete only when the raw value is absent from every unintended path.", bullets: ["Test nested objects and arrays.", "Test sampling and retries for accidental duplication.", "Audit support and export paths.", "Verify deletion of derived data, not only primary events."] },
    ],
    sources: [source("OpenTelemetry MCP conventions", "https://github.com/open-telemetry/semantic-conventions-genai/blob/main/docs/gen-ai/mcp.md"), source("MCP Apps security model", "https://apps.extensions.modelcontextprotocol.io/api/documents/overview.html"), source("TrackMCP security", "https://trackmcp.com/security")],
    faq: [["Can a dashboard mask fix an unredacted event?", "No. Redaction must happen before telemetry leaves the process. Storage and dashboard masking cannot repair copies already exported to logs or queues."], ["Should error messages be captured?", "Only after classification and redaction. Error text often includes customer data, URLs, identifiers, or dependency responses."]],
  },
  "mcp-observability-data-retention": {
    context: "Retention should be based on the evidence a team needs, not on a default storage window. OpenTelemetry makes sensitive arguments and results opt-in. TrackMCP's docs describe bounded, redacted payload modes and local redaction. A mature retention policy separates short-lived payloads, medium-term reliability aggregates, longer-term catalog and release history, and case-bound incident evidence.",
    tools: ["TrackMCP retention controls", "OpenTelemetry Collector", "Grafana Loki and Tempo", "Sentry retention", "Datadog retention", "Langfuse retention"],
    sections: [
      { heading: "Give every signal a half-life", body: "A raw argument may be useful for a short approved investigation, while a monthly p95 trend or catalog history may be useful for much longer. Retain the minimum metadata needed to interpret an aggregate after raw events expire: server, tool, client, release, environment, timestamp, result category, and sampling state. Keep incident evidence under an owner and expiry date.", bullets: ["Short-lived sampled payloads, when approved.", "Medium-term tool, client, latency, and error aggregates.", "Longer-term catalog, release, and SLO history.", "Case-bound evidence with an explicit deletion date."] },
      { heading: "Test deletion across the data path", body: "A deletion policy must include primary events, indexes, derived aggregates, exports, backups, and support copies. Define the workspace or subject identifier required to find the data without using a secret. Run a fixture through ingestion, retry, aggregation, export, and deletion, then record the deletion operation and its scope.", bullets: ["Document primary and derived retention.", "Test partial ingestion and retry cases.", "Audit export and backup behavior.", "Keep an audit record of the operation, not the deleted payload."] },
    ],
    sources: [source("TrackMCP documentation", "https://trackmcp.com/docs"), source("OpenTelemetry MCP conventions", "https://github.com/open-telemetry/semantic-conventions-genai/blob/main/docs/gen-ai/mcp.md"), source("TrackMCP security", "https://trackmcp.com/security")],
    faq: [["How long should MCP telemetry be retained?", "There is no universal window. Use a tiered policy based on signal value, privacy risk, incident windows, and applicable requirements."], ["Do aggregates require deletion too?", "Yes. Derived aggregates can still be linked to a customer, user, server, or workspace and belong in the retention review."]],
  },
  "mcp-server-error-rate": {
    context: "MCP error rate is not one number. OpenTelemetry's MCP conventions distinguish operation errors and recommend method, tool, protocol, session, and transport attributes. Sentry's MCP monitoring shows per-tool error rate and p95, while TrackMCP emphasizes application errors inside successful transport responses. The article should teach readers to separate transport, protocol, tool result, timeout, cancellation, retry, and unknown side-effect states before aggregating.",
    tools: ["TrackMCP", "Sentry MCP monitoring", "OpenTelemetry MCP conventions", "Grafana Prometheus", "Datadog APM"],
    sections: [
      { heading: "Define numerator and denominator by layer", body: "Use connections for negotiation success, calls for tool result errors, and workflows for completion. A transport 500 is not the same as an MCP tool result with isError. A cancellation is not always a handler failure. An unknown side-effect state deserves its own risk measure because a retry can create a duplicate operation. Publish the denominator with every percentage.", bullets: ["Connection and authentication rejection.", "Protocol or wire-schema error.", "Tool result application error.", "Timeout, cancellation, retry, and unknown state."] },
      { heading: "Use cardinality for ownership, not decoration", body: "Break down errors by server, environment, release, client, tool, and category. Avoid unbounded error messages as labels. A useful alert says which owner, tool, client, and release are affected and includes a redacted evidence sample. A generic “MCP error rate high” alert forces responders to repeat the analysis manually.", bullets: ["Use minimum traffic and sustained-window guards.", "Keep category values bounded.", "Link the first broken event and runbook.", "Alert separately on result errors and unknown side effects."] },
    ],
    sources: [source("OpenTelemetry MCP conventions", "https://github.com/open-telemetry/semantic-conventions-genai/blob/main/docs/gen-ai/mcp.md"), source("Sentry MCP monitoring", "https://sentry.io/cookbook/monitor-mcp-server/"), source("TrackMCP observability", "https://trackmcp.com/mcp-observability")],
    faq: [["Does HTTP 500 equal an MCP tool error?", "No. HTTP status describes the outer transport. A valid MCP response can still carry a tool-level application error."], ["Should cancellations count as errors?", "Track them separately. A cancellation can be expected, client-driven, or evidence of a deadline or capacity problem."]],
  },
  "mcp-server-latency-slo": {
    context: "MCP latency needs several clocks. OpenTelemetry defines client and server operation duration and session duration. Grafana documents MCP server metrics and traces. Sentry exposes average and p95 tool duration. These measurements are useful only when the article distinguishes server execution, gateway wait, dependency time, client wait, and end-to-end workflow time. A p50 alone is not an SLO for an agent workflow.",
    tools: ["TrackMCP latency analytics", "Sentry p95 tool monitoring", "Grafana Prometheus and Tempo", "OpenTelemetry MCP conventions", "Datadog APM"],
    sections: [
      { heading: "Name the timer before setting the target", body: "Server duration starts when the MCP process accepts the operation and ends when it produces a result. Client wait includes transport and gateway behavior. End-to-end workflow time includes model and other tools. Set objectives by tool class and client deadline, then allocate a budget to dependencies, retries, and queueing. Otherwise teams can improve a timer while users still wait longer.", bullets: ["Track p50, p95, and p99 by tool and client.", "Separate dependency time from handler time.", "Measure timeout and cancellation rates.", "Keep durable work on an explicit task contract."] },
      { heading: "Make a slow tail explainable", body: "A useful slow event shows release, client, tool, dependency category, retry state, and outcome. Keep high-cardinality payloads out of routine labels. Compare tail behavior before and after a catalog, SDK, gateway, or dependency change. If a client stops waiting while the server continues, record unknown side-effect state and reconcile before retrying.", bullets: ["Alert on sustained tail regression, not one outlier.", "Link a redacted trace or event sample.", "Compare client-visible and server timings.", "Add reconciliation to write-path runbooks."] },
    ],
    sources: [source("OpenTelemetry MCP conventions", "https://github.com/open-telemetry/semantic-conventions-genai/blob/main/docs/gen-ai/mcp.md"), source("Grafana MCP observability", "https://grafana.com/docs/grafana-cloud/ai-tools/mcp-servers/oss-mcp/developer/observability-metrics-and-tracing/"), source("Sentry MCP monitoring", "https://sentry.io/cookbook/monitor-mcp-server/")],
    faq: [["Should every MCP tool share one latency target?", "No. Interactive reads, searches, writes, and durable work have different deadlines and outcome expectations."], ["Does a timeout prove the server failed?", "No. The client may have stopped waiting while the server or dependency continued. Reconcile unknown state before repeating a side effect."]],
  },
  "mcp-server-uptime-vs-health": {
    context: "An HTTP check only answers whether an endpoint responded. TrackMCP's health check and tester deliberately report negotiation, capabilities, catalogs, pagination, latency, authentication, browser compatibility, and findings as separate dimensions. The official MCP conformance framework adds wire-schema and scenario checks. This gives a precise distinction between uptime, protocol health, catalog health, tool health, and workflow health.",
    tools: ["TrackMCP health check", "TrackMCP server tester", "MCP Conformance Test Framework", "MCP Inspector", "Grafana synthetic monitoring"],
    sections: [
      { heading: "Design a health score with dimensions", body: "Do not collapse reachability, auth, negotiation, catalog quality, tool result, latency, and workflow completion into one unexplained green number. A server can be reachable but unauthorized, negotiated but missing a tool, or healthy at the protocol layer while every application call fails. Each dimension should name its evidence source and its remediation owner.", bullets: ["Reachability and TLS.", "Authorization challenge and token validation.", "Protocol revision and capabilities.", "Catalog completeness and schema quality.", "Tool result, latency, and outcome."] },
      { heading: "Use synthetic checks carefully", body: "A public health probe should be read-only, bounded, and explicit about incomplete results. Synthetic tool calls belong in a controlled fixture with safe credentials and side-effect assertions. Real traffic telemetry remains necessary because a probe cannot represent every client, permission, dependency, or workflow.", bullets: ["Reject private and metadata targets.", "Bound bodies, pagination, duration, and cancellation.", "Report CORS-blocked separately from server-down.", "Run post-deployment and after auth or gateway changes."] },
    ],
    sources: [source("TrackMCP health check", "https://trackmcp.com/tools/mcp-health-check"), source("TrackMCP server tester", "https://trackmcp.com/tools/mcp-server-tester"), source("MCP conformance framework", "https://github.com/modelcontextprotocol/conformance")],
    faq: [["Can an HTTP 200 endpoint be unhealthy?", "Yes. Protocol errors, broken catalogs, application errors, or unacceptable latency can all occur inside a successful transport response."], ["Does a health check prove a workflow works?", "Only if it executes a controlled, explicit synthetic workflow. A generic read-only probe cannot prove business completion."]],
  },
  "mcp-server-debugging-production": {
    context: "Production debugging is where server-boundary evidence earns its value. The MCP conformance suite can tell you whether a protocol scenario fails, while Sentry, Grafana, Datadog, Langfuse, and TrackMCP can show different parts of a live failure. The safest workflow starts with the first broken event, protects state-changing tools, and uses a redacted reproduction instead of enabling unrestricted payload logging.",
    tools: ["TrackMCP", "MCP Conformance", "Sentry", "Grafana", "Datadog", "Langfuse"],
    sections: [
      { heading: "Triage from symptom to boundary", body: "Write the symptom in user terms, then classify it as endpoint, auth, protocol, catalog, tool, dependency, client, or outcome. Capture server, client, tool, release, environment, and time window. Follow the ordered session and compare it with a known-good path. Later errors often describe consequences of an earlier catalog, authorization, or dependency failure.", bullets: ["Freeze the incident question.", "Find the first divergence from a known-good sequence.", "Separate client wait from server and dependency time.", "Mark sampled or missing evidence explicitly."] },
      { heading: "Mitigate without creating a second incident", body: "Rollback one release, gate one broken tool, route a client cohort, or adjust a bounded dependency budget before applying broad retries. For writes, reconcile unknown state before repeating. Preserve a minimal redacted event and turn it into a regression test through the real transport and auth path.", bullets: ["Prefer reversible controls.", "Do not replay arbitrary production writes.", "Keep raw payload logging out of the default runbook.", "Close with an owner, test, and evidence gap list."] },
    ],
    sources: [source("TrackMCP troubleshooting", "https://trackmcp.com/docs/troubleshooting"), source("MCP conformance framework", "https://github.com/modelcontextprotocol/conformance"), source("Langfuse MCP tracing", "https://langfuse.com/docs/observability/features/mcp-tracing")],
    faq: [["Should I enable raw payload logging during an incident?", "Only with an approved, temporary, redacted diagnostic mode. Raw arguments and results can turn a reliability incident into a privacy incident."], ["What is the best first query?", "Find the affected server, client, tool, release, and time window, then inspect the ordered boundary events for the first divergence from a known-good workflow."]],
  },
  "mcp-server-incident-response": {
    context: "MCP incident response needs to protect both reliability and tool side effects. The official authorization guidance distinguishes HTTP 401 discovery from tool-level errors. The conformance framework distinguishes protocol failures from application behavior. TrackMCP's server-boundary model can preserve tool, client, retry, latency, and outcome evidence. A runbook should combine these rather than treating every “MCP is down” report as a transport outage.",
    tools: ["TrackMCP", "MCP Conformance", "Sentry Issues", "Grafana Alerting", "Datadog Monitors", "MCP Inspector"],
    sections: [
      { heading: "Use an incident taxonomy", body: "Classify the report through endpoint, authentication, protocol, catalog, tool result, dependency, latency, retry, and outcome stages. Authentication discovery can legitimately start with 401 and a protected-resource metadata challenge. A tool result error inside 200 is a different failure. A client cancellation may leave a write in an unknown state. Each class needs a different mitigation and evidence source.", bullets: ["Record the first broken event and its source.", "Keep auth, protocol, application, and outcome categories separate.", "Protect write tools during mitigation.", "Route alerts to the owner of the implicated boundary."] },
      { heading: "Finish with evidence, not a status page", body: "Compare the affected release with baseline error, latency, catalog, retry, and outcome signals. Record what was not observed. Add a canary, conformance case, catalog diff, or redaction fixture that would have caught the incident earlier. An incident is not closed because the endpoint is green; it is closed when the user-impacting path is explained and protected.", bullets: ["Attach a redacted first-failure example.", "Document unknown side effects and reconciliation.", "Add a regression check before closing.", "Update alert thresholds and ownership."] },
    ],
    sources: [source("MCP Apps authorization", "https://apps.extensions.modelcontextprotocol.io/api/documents/authorization.html"), source("MCP conformance framework", "https://github.com/modelcontextprotocol/conformance"), source("TrackMCP observability", "https://trackmcp.com/mcp-observability")],
    faq: [["Should telemetry outage page the server on-call?", "Page when missing evidence creates a defined user-impacting blind spot or violates an evidence SLO. Do not make an analytics outage block serving by default."], ["What belongs in an MCP postmortem?", "User impact, first broken event, boundary classification, mitigation, state-safety decisions, missing evidence, and the control or test added afterward."]],
  },
  "mcp-tool-failure-analysis": {
    context: "MCP tool failures have more than one failure mode. OpenTelemetry's conventions record MCP method, tool, error type, protocol, session, and transport attributes. Sentry highlights most failing tools and silent errors. TrackMCP can preserve result state at the server boundary. Failure analysis should therefore follow the ordered call sequence and classify the first divergence instead of ranking a flat list of error strings.",
    tools: ["TrackMCP tool analytics", "Sentry MCP monitoring", "OpenTelemetry MCP conventions", "Grafana Tempo", "MCP Conformance"],
    sections: [
      { heading: "Separate selection, execution, and outcome", body: "A client can select a valid tool and receive an application failure. It can also fail to select a good tool because its description or schema is poor. The server can observe calls and results, but host-side selection context may require client instrumentation. Keep those claims separate, then connect them with a workflow identifier when one exists.", bullets: ["Catalog exposure and candidate selection.", "Tool invocation and validation.", "Dependency and application result.", "Retry, reconciliation, and final outcome."] },
      { heading: "Turn the first failure into a test", body: "Capture the smallest non-sensitive reproducer, run it through the real transport and auth path, and assert both protocol result and downstream state. Add cases for invalid arguments, authorization, dependency failure, timeout, cancellation, and duplicate operation identity. A valid error response is not enough if the handler performed a side effect.", bullets: ["Keep fixtures deterministic.", "Test result shape and error category.", "Assert side-effect state for writes.", "Record the release and client that exposed the failure."] },
    ],
    sources: [source("OpenTelemetry MCP conventions", "https://github.com/open-telemetry/semantic-conventions-genai/blob/main/docs/gen-ai/mcp.md"), source("Sentry MCP monitoring", "https://sentry.io/cookbook/monitor-mcp-server/"), source("MCP conformance framework", "https://github.com/modelcontextprotocol/conformance")],
    faq: [["Can a tool error be hidden by 200?", "Yes. A valid MCP response can contain an application-level error even when the outer transport succeeded."], ["What is the first failure to investigate?", "The first divergence in the ordered call sequence, compared with a known-good workflow. Later errors may be consequences."]],
  },
  "mcp-200-ok-application-errors": {
    context: "The 200 OK blind spot is a core MCP observability problem. Tool results can carry application-level errors inside a valid protocol response, and OpenTelemetry's MCP conventions provide explicit error attributes for operations. Sentry's MCP monitoring explicitly calls out silent errors. TrackMCP is relevant because server-boundary instrumentation can see the result state before it leaves the process.",
    tools: ["TrackMCP", "Sentry MCP monitoring", "OpenTelemetry MCP conventions", "Grafana Prometheus", "Datadog APM"],
    sections: [
      { heading: "Instrument after the handler returns", body: "Capture transport status, protocol result, tool identity, duration, retry context, and application error state separately. The correct location is the result boundary after the handler has produced the MCP response and before the response is sent. Do not convert every application error into an HTTP error if that breaks the protocol contract, and do not erase the result error to keep the transport green.", bullets: ["Keep transport and result status as separate fields.", "Bound and redact error details.", "Record dependency category without raw payloads.", "Emit a workflow outcome only when the application can prove it."] },
      { heading: "Test the dashboard blind spot", body: "Create a fixture that returns 200 plus a result error, then verify metrics, alerts, incident routing, and client behavior. Repeat with a retry, cancellation, and successful reconciliation. If the system counts the first error as a success or double-counts a later retry, the metric contract is not ready for production.", bullets: ["Add a 200-plus-error CI fixture.", "Break down by tool, client, release, and environment.", "Alert on sustained result errors, not expected validation misses.", "Keep unknown side effects visible."] },
    ],
    sources: [source("TrackMCP observability", "https://trackmcp.com/mcp-observability"), source("Sentry MCP monitoring", "https://sentry.io/cookbook/monitor-mcp-server/"), source("OpenTelemetry MCP conventions", "https://github.com/open-telemetry/semantic-conventions-genai/blob/main/docs/gen-ai/mcp.md")],
    faq: [["Should a tool-level error become HTTP 500?", "Not automatically. Preserve the MCP result contract and instrument the application error explicitly. Transport status and tool result state are different signals."], ["Can generic APM catch this?", "Only if the MCP instrumentation records the result error. A generic HTTP span may otherwise appear successful."]],
  },
  "mcp-tool-usage-report": {
    context: "MCP tool usage is a product and reliability question, not a call leaderboard. The official client best practices recommend progressive discovery because large catalogs consume context. Glama's directory API and the official registry help describe available servers, while runtime telemetry is needed to see what clients actually call. A useful report joins exposure, selection, calls, result state, latency, retries, and explicit outcomes.",
    tools: ["TrackMCP tool analytics", "Official MCP Registry", "Glama", "Smithery", "Sentry", "Langfuse"],
    sections: [
      { heading: "Measure the full adoption path", body: "Keep discovered, selected, called, returned, and completed as separate stages. A server can know a tool was called without knowing why it was selected. A host-side trace can add selection or model context. Do not claim that an uncalled tool has no demand when the client or catalog evidence is incomplete. Mark sampled and unknown cohorts explicitly.", bullets: ["Catalog exposure and schema version.", "Client and environment mix.", "Call, result, error, latency, and retry.", "Workflow outcome after the call."] },
      { heading: "Use reports to improve the product", body: "A high call count with low completion is a warning, not a success. Investigate descriptions, schemas, authorization, dependency time, and alternative tools. Compare a catalog or implementation change against client-specific selection, error, latency, and outcome metrics. Retire tools only after owner review and a migration path.", bullets: ["Identify catalog gaps and misleading descriptions.", "Review newly unused and newly overloaded tools.", "Compare changes by release and client.", "Keep business value as an explicit application signal."] },
    ],
    sources: [source("MCP client best practices", "https://github.com/modelcontextprotocol/modelcontextprotocol/blob/main/docs/docs/2026-07-28/develop/clients/client-best-practices.mdx"), source("Glama MCP API", "https://glama.ai/mcp/reference"), source("TrackMCP tool analytics", "https://trackmcp.com/tool-analytics")],
    faq: [["Can server telemetry measure tool selection?", "It can observe calls. The reason a client selected or ignored a tool may require host-side context or a separate client integration."], ["What should replace a raw call leaderboard?", "A report that combines exposure, calls, result reliability, latency, retries, and explicit workflow outcomes for a defined cohort."]],
  },
  "mcp-client-analytics": {
    context: "Client analytics is useful because the same MCP server can behave differently for Claude, Cursor, ChatGPT, or a custom client. The server may receive client metadata, but identity is not always present or trustworthy. Datadog documents client-side MCP instrumentation, while Langfuse shows how client and server traces can be linked. TrackMCP can provide server-side client mix and behavior without claiming visibility into private model turns.",
    tools: ["TrackMCP client analytics", "Claude", "Cursor", "ChatGPT", "Datadog MCP client monitoring", "Langfuse"],
    sections: [
      { heading: "Treat client identity as evidence with confidence", body: "Store client name and version when provided, plus the source and timestamp. A custom client can omit or spoof the name. Never use an unverified client label as an authorization decision or as proof of the model provider. Keep unknown clients visible and investigate by transport, auth, release, and behavior.", bullets: ["Client name and version when available.", "Protocol revision, transport, and auth mode.", "Server release and environment.", "Identity source and confidence."] },
      { heading: "Compare behavior by client", body: "Break down negotiation, catalog exposure, tool selection, result errors, latency, retries, cancellations, and workflow outcomes. A small client cohort can reveal a schema or transport regression before a global average moves. Reproduce through the same gateway and credentials before blaming either client or server.", bullets: ["Keep a supported-client matrix.", "Compare before and after catalog or protocol changes.", "Separate client wait from server execution.", "Route support reports to evidence, not anecdotes."] },
    ],
    sources: [source("Datadog MCP client monitoring", "https://docs.datadoghq.com/llm_observability/guide/monitor_mcp_client/"), source("Langfuse MCP tracing", "https://langfuse.com/docs/observability/features/mcp-tracing"), source("TrackMCP analytics", "https://trackmcp.com/mcp-server-analytics")],
    faq: [["Can server analytics see the model a client used?", "Not necessarily. It can observe client metadata and server requests. Model and prompt context requires a host-side integration."], ["What if clients omit their names?", "Keep them unknown rather than guessing. Use transport, auth, release, and behavior to form a cohort."]],
  },
  "mcp-workflow-funnels": {
    context: "MCP sessions are not automatically user workflows. A server can observe connections, catalog discovery, calls, results, retries, and sometimes an explicit outcome. The official client guidance separates discovery, schema inspection, and execution, while TrackMCP emphasizes explicit workflow signals. A funnel should therefore show evidence-backed stages and mark partial, sampled, canceled, and unknown sessions instead of inventing completion.",
    tools: ["TrackMCP workflow analytics", "Langfuse traces", "Sentry traces", "OpenTelemetry MCP sessions", "Datadog Agent Observability"],
    sections: [
      { heading: "Define stage ownership", body: "Connection, authorization, and catalog discovery are protocol evidence. Tool execution and result state are server evidence. Selection context may belong to the host. Completion belongs to the application that can prove the user's operation ended. Use a stable operation or workflow ID when available, and never infer a final user goal from a call sequence alone.", bullets: ["Connected and authorized.", "Catalog discovered and candidate selected.", "Tool returned a result.", "Recovery or retry occurred.", "Application emitted completion or failure."] },
      { heading: "Use drop-off as a hypothesis, not a verdict", body: "If discovery is high but calls are low, investigate context cost, descriptions, schemas, permissions, and client behavior. If calls succeed but outcomes are low, inspect downstream business logic. If retries rise after a release, compare latency and unknown side-effect state. Each drop-off needs a controlled change and a matched cohort.", bullets: ["Keep sampling and missing events visible.", "Separate cancellation from failure.", "Measure reliability and latency with conversion.", "Roll back when adoption rises but safety or outcomes fall."] },
    ],
    sources: [source("MCP client best practices", "https://github.com/modelcontextprotocol/modelcontextprotocol/blob/main/docs/docs/2026-07-28/develop/clients/client-best-practices.mdx"), source("Langfuse MCP tracing", "https://langfuse.com/docs/observability/features/mcp-tracing"), source("TrackMCP analytics", "https://trackmcp.com/mcp-server-analytics")],
    faq: [["Is every MCP session a workflow?", "No. It can be discovery, a probe, partial work, or an abandoned connection. Use explicit workflow context for task-level claims."], ["What is the best funnel conversion metric?", "Explicit completion for a defined cohort, supported by the intermediate stages that explain why it changed."]],
  },
  "mcp-tool-adoption-benchmark": {
    context: "A universal MCP adoption benchmark would be misleading because catalogs, clients, workflows, and evidence coverage differ. Progressive discovery guidance makes exposure and context cost important, while registries such as the official registry, Glama, and Smithery describe supply rather than actual usage. A benchmark should compare matched cohorts and measure the path from exposure to a useful outcome.",
    tools: ["TrackMCP tool analytics", "Official MCP Registry", "Glama", "Smithery", "Langfuse", "Sentry"],
    sections: [
      { heading: "Define the cohort before the percentage", body: "Record server domain, environment, client mix, catalog version, release, time window, traffic volume, and evidence coverage. A tool available to every client cannot be compared directly with one exposed to a single workflow. Keep unknown and sampled traffic in the benchmark metadata so a false increase in coverage does not look like adoption.", bullets: ["Match server and workflow class.", "Match client and catalog version.", "Set minimum traffic and evidence thresholds.", "Compare change over time before comparing peers."] },
      { heading: "Benchmark usefulness, not popularity", body: "Measure exposed, selected or called, result-successful, and workflow-completed states with latency, errors, retries, and safety constraints. A tool can be popular because its alternatives are worse. Adoption growth that lowers completion or increases unsafe side effects is a regression, not a win.", bullets: ["Pair adoption with outcome and error metrics.", "Segment by client and workflow.", "Document hidden or unobserved host behavior.", "Review catalog and permission changes with owners."] },
    ],
    sources: [source("MCP client best practices", "https://github.com/modelcontextprotocol/modelcontextprotocol/blob/main/docs/docs/2026-07-28/develop/clients/client-best-practices.mdx"), source("Official MCP Registry", "https://registry.modelcontextprotocol.io/"), source("Glama MCP directory", "https://glama.ai/mcp/servers")],
    faq: [["What is a healthy adoption rate?", "It depends on exposure, workflow eligibility, client mix, and outcome. Use a defined cohort and trend rather than a universal percentage."], ["Should low-adoption tools be deleted?", "First check exposure, descriptions, permissions, and hidden clients. Retire only with owner review and a migration path."]],
  },
  "mcp-schema-regression-monitoring": {
    context: "Schema monitoring needs to cover more than JSON validity. MCP tools are selected through names, titles, descriptions, annotations, input schemas, and output contracts. The official conformance framework checks wire behavior, while client best practices emphasize progressive discovery and schema loading. A breaking change can remain syntactically valid while changing required fields, enums, output shape, or selection behavior.",
    tools: ["MCP Conformance", "MCP Inspector", "TrackMCP catalog analytics", "OpenAPI or JSON Schema validators", "Sentry", "Grafana"],
    sections: [
      { heading: "Snapshot the contract clients see", body: "Version tool name, title, description, input schema, output schema, annotations, capabilities, server release, and authorization scope. Classify changes as compatible, risky, or breaking for supported clients and workflows. A tool rename can affect caches, permissions, analytics continuity, and learned client behavior even when the handler still works.", bullets: ["Required and optional property changes.", "Type and enum changes.", "Output and error-shape changes.", "Description, annotation, and permission changes."] },
      { heading: "Test selection and execution separately", body: "A schema diff cannot prove that a client will select the tool or that the handler returns the promised shape. Run supported clients or a harness against the changed catalog, then exercise valid, invalid, boundary, unauthorized, and side-effect inputs. Keep the test transport and gateway close to production.", bullets: ["Validate generated and hand-written client calls.", "Exercise invalid and missing arguments.", "Assert output and error contracts.", "Test state changes in disposable fixtures."] },
    ],
    sources: [source("MCP tools specification", "https://modelcontextprotocol.org/specification/2026-07-28/server/tools"), source("MCP conformance framework", "https://github.com/modelcontextprotocol/conformance"), source("MCP client best practices", "https://github.com/modelcontextprotocol/modelcontextprotocol/blob/main/docs/docs/2026-07-28/develop/clients/client-best-practices.mdx")],
    faq: [["Is schema validation enough?", "No. It catches structure, not client selection, authorization, side effects, latency, or business correctness."], ["What should block a release?", "Unreviewed required-field, output, permission, safety, or identity changes should block or require an explicit migration plan."]],
  },
  "mcp-catalog-drift": {
    context: "Catalog drift is a governance and production reliability issue. The official registry, Glama, and Smithery can describe published servers, but only a live endpoint reveals the catalog clients actually discover. MCP client best practices also make catalog size, filtering, pagination, and list-changed behavior operational concerns. TrackMCP can connect catalog evidence to the client and tool traffic that follows it.",
    tools: ["TrackMCP catalog analytics", "Official MCP Registry", "Glama", "Smithery", "MCP Inspector", "MCP Conformance"],
    sections: [
      { heading: "Track four catalog states", body: "Keep declared, discovered, tested, and approved separate. A registry entry is declared. A live probe is discovered. A conformance or contract suite is tested. Security and product review make it approved. Each state needs owner, source, timestamp, endpoint, release, and policy provenance. Do not let a stale README stand in for a live catalog.", bullets: ["Compare tools, resources, prompts, and capabilities.", "Record schema and annotation changes.", "Track transport, auth, and scope changes.", "Keep stale or unknown evidence visible."] },
      { heading: "Connect drift to usage", body: "After a change, compare client discovery, calls, errors, latency, retries, and outcomes with the previous catalog. A file can match while a gateway, authorization scope, or deployment serves something else. Watch for unexpected exposure, newly unused tools, and a client-specific selection regression.", bullets: ["Run preflight against the deployed endpoint.", "Keep catalog and release markers joinable.", "Alert on high-risk additions and removals.", "Provide rollback and migration ownership."] },
    ],
    sources: [source("Official MCP Registry", "https://registry.modelcontextprotocol.io/"), source("MCP client best practices", "https://github.com/modelcontextprotocol/modelcontextprotocol/blob/main/docs/docs/2026-07-28/develop/clients/client-best-practices.mdx"), source("Glama MCP API", "https://glama.ai/mcp/reference")],
    faq: [["Can a registry prevent drift?", "No. It can describe intended servers and publishers. It cannot prove that a live endpoint still exposes the same catalog or behavior."], ["Should every catalog change block deployment?", "Use risk-based policy. Access, identity, permission, and breaking schema changes deserve stronger gates than an approved additive read tool."]],
  },
  "mcp-server-release-monitoring": {
    context: "A release marker becomes useful when it joins deployment identity to live MCP behavior. The conformance framework supports revision-specific requirements and expected-failure baselines. OpenTelemetry and Grafana provide transport and trace context, while TrackMCP can expose server, client, tool, catalog, latency, error, retry, and outcome changes. Release monitoring should catch traffic regressions that CI cannot know about.",
    tools: ["MCP Conformance", "TrackMCP release analytics", "Grafana", "Sentry Releases", "Datadog Deployment Tracking", "OpenTelemetry"],
    sections: [
      { heading: "Mark all behavior-changing inputs", body: "Record build revision, SDK and runtime, protocol revision, transport, gateway, auth policy, catalog snapshot, dependency versions, region, and rollout cohort. Keep the marker stable through canary and full rollout. Without those fields, a regression after an SDK upgrade can look like a client or dependency issue.", bullets: ["Join release to live events.", "Keep catalog and authorization versions.", "Record region and rollout percentage.", "Avoid secrets and unbounded free-form labels."] },
      { heading: "Define rollback evidence before rollout", body: "Set minimum volume and sustained-window criteria for result errors, p95 and p99 latency, auth rejection, catalog mismatch, retries, unknown side effects, and workflow completion. Compare the same client and tool cohorts before and after the release. Rollback is safer when the failure can be tied to a release and verified after recovery.", bullets: ["Use canaries and reversible controls.", "Protect write tools during rollback.", "Preserve failed-release evidence.", "Turn the failure into conformance or contract coverage."] },
    ],
    sources: [source("MCP conformance framework", "https://github.com/modelcontextprotocol/conformance"), source("OpenTelemetry MCP conventions", "https://github.com/open-telemetry/semantic-conventions-genai/blob/main/docs/gen-ai/mcp.md"), source("TrackMCP docs", "https://trackmcp.com/docs")],
    faq: [["Can release monitoring replace CI?", "No. CI catches known contract and conformance failures before deployment. Live release monitoring catches real traffic, client, gateway, dependency, and environment behavior."], ["How long should a release be watched?", "Long enough to cover critical clients and workflows, plus low-volume or delayed paths that a short canary can miss."]],
  },
  "mcp-observability-open-telemetry-integration": {
    context: "OpenTelemetry's MCP semantic conventions are still evolving, but they already describe domain-specific spans and metrics for MCP operations, sessions, methods, tools, transports, and context propagation. The conventions explicitly say generic HTTP or RPC semantics do not capture streaming MCP message exchanges. Grafana demonstrates exporting MCP metrics, traces, and logs. A useful integration guide must preserve MCP meaning instead of flattening everything into generic spans.",
    tools: ["OpenTelemetry MCP semantic conventions", "OpenTelemetry Collector", "Grafana Tempo", "Prometheus", "Loki", "TrackMCP"],
    sections: [
      { heading: "Map MCP fields deliberately", body: "Keep method, tool, prompt, resource, session, protocol revision, transport, error type, client, catalog, retry, cancellation, and outcome fields explicit. Use low-cardinality names for span names and opt in to arguments or results only with a privacy policy. Propagate W3C context in MCP metadata only when the client and server agree on the contract.", bullets: ["Separate MCP and underlying transport context.", "Use server and client span ownership.", "Keep tool and prompt names bounded.", "Record sampling and missing-span behavior."] },
      { heading: "Validate the exporter under failure", body: "Compare a raw MCP-boundary fixture with the exported record. Test a 200-plus-application-error, retry, cancellation, slow dependency, shutdown, queue pressure, and exporter outage. The server should continue serving according to its contract, and redaction should happen before the collector or exporter receives the event.", bullets: ["Measure exporter overhead separately.", "Bound event size and queue length.", "Verify opt-in payload capture.", "Route missing telemetry to an evidence alert, not a serving failure."] },
    ],
    sources: [source("OpenTelemetry MCP conventions", "https://github.com/open-telemetry/semantic-conventions-genai/blob/main/docs/gen-ai/mcp.md"), source("Grafana MCP observability", "https://grafana.com/docs/grafana-cloud/ai-tools/mcp-servers/oss-mcp/developer/observability-metrics-and-tracing/"), source("OpenTelemetry GenAI repository", "https://github.com/open-telemetry/semantic-conventions-genai")],
    faq: [["Does OpenTelemetry automatically understand MCP?", "No. Use MCP-aware instrumentation and map its semantics deliberately. Generic HTTP spans do not capture all messages in streaming MCP transports."], ["Should every MCP event be a span?", "Not necessarily. Use spans, metrics, and events according to query, cost, and ordering needs, while preserving MCP-specific fields."]],
  },
  "mcp-observability-grafana-sentry-datadog": {
    context: "Grafana, Sentry, and Datadog are real MCP-adjacent options, but they have different centers of gravity. Grafana documents MCP metrics, traces, and logs and its MCP server supports several transports and read-only controls. Sentry documents MCP server monitoring with tool and resource performance, silent errors, and trace exploration. Datadog's MCP Server exposes observability data to AI clients, while Datadog also documents client instrumentation. TrackMCP should be positioned around the server-boundary analytics gap.",
    tools: ["TrackMCP", "Grafana and Tempo", "Sentry MCP monitoring", "Datadog MCP Server", "Langfuse", "OpenTelemetry"],
    sections: [
      { heading: "Compare the question each system owns", body: "Grafana is often the flexible metrics, logs, and traces layer. Sentry is strong for application errors, issues, releases, and trace samples. Datadog combines infrastructure, APM, logs, monitors, and an MCP interface for querying that data. Langfuse focuses on model and agent traces. TrackMCP is most differentiated when a team needs server-boundary client, catalog, tool, result, retry, and outcome analytics without building that semantic layer from generic spans.", bullets: ["Document instrumentation location.", "Test application errors inside successful transport responses.", "Check client, catalog, tool, and outcome dimensions.", "Separate system used to observe MCP from an MCP server used to query observability data."] },
      { heading: "Run one neutral comparison fixture", body: "Use a healthy call, silent application error, slow dependency, catalog change, retry, and explicit completion. Ask each product to show the first broken event, client, tool, release, and evidence boundary. Record what is not observed. This avoids inaccurate claims that one vendor replaces another and gives TrackMCP a clear server-owner use case.", bullets: ["Keep privacy and retention modes equivalent.", "Test stdio and Streamable HTTP where claimed.", "Measure setup and incident query time.", "Keep a layered stack when the evidence is complementary."] },
    ],
    sources: [source("Grafana MCP observability", "https://grafana.com/docs/grafana-cloud/ai-tools/mcp-servers/oss-mcp/developer/observability-metrics-and-tracing/"), source("Sentry MCP monitoring", "https://sentry.io/cookbook/monitor-mcp-server/"), source("Datadog MCP Server", "https://docs.datadoghq.com/mcp_server/"), source("Langfuse MCP tracing", "https://langfuse.com/docs/observability/features/mcp-tracing")],
    faq: [["Can Sentry or Datadog monitor an MCP server?", "Yes, they can provide valuable application, error, infrastructure, and trace signals. Verify which MCP-specific catalog, result, client, and outcome fields your integration captures."], ["Is Grafana a competitor or a complement?", "It can be either depending on the deployment. Grafana is often complementary for metrics, logs, traces, and infrastructure while TrackMCP focuses on server-boundary MCP analytics."]],
  },
  "mcp-observability-buyers-guide": {
    context: "A buyer's guide should make vendors prove their claims against the buyer's server and failure modes. The current ecosystem includes focused MCP analytics, Sentry's MCP monitoring, Grafana's MCP metrics and traces, Datadog's broad observability and MCP access, Langfuse linked traces, OpenTelemetry conventions, and diagnostic tools such as the official conformance suite and TrackMCP tester. The evaluation should reward evidence quality, boundary fit, privacy, and operating value.",
    tools: ["TrackMCP", "Sentry", "Grafana", "Datadog", "Langfuse", "OpenTelemetry", "MCP Conformance"],
    sections: [
      { heading: "Write the RFP around questions", body: "Ask who connected, what catalog was exposed, which tool failed, why latency rose, whether a result was an application error, what was retried, and whether the workflow completed. Add privacy questions about arguments, results, redaction, retention, deletion, exports, and support access. Require a vendor to show the evidence and state what it cannot see.", bullets: ["Boundary and signal coverage.", "Setup and SDK behavior.", "Client and catalog dimensions.", "Privacy, access, retention, and deletion.", "Incident query speed and evidence quality."] },
      { heading: "Use a proof-of-value scorecard", body: "Give each candidate the same production-like server and redacted fixtures. Require a healthy call, 200-plus-application-error, slow dependency, retry, catalog drift, and explicit outcome. Score the explanation and time to action, not the number of pages in a dashboard. Include the cost of keeping the integration correct as MCP revisions and clients change.", bullets: ["Use a named owner and review window.", "Record missing evidence as a disqualifier when it affects the primary question.", "Test export, deletion, and outage behavior.", "Compare total operating cost over the period you will run it."] },
    ],
    sources: [source("TrackMCP observability comparison", "https://trackmcp.com/blog/best-mcp-observability-tools-for-production-servers"), source("Sentry MCP monitoring", "https://sentry.io/cookbook/monitor-mcp-server/"), source("Grafana MCP observability", "https://grafana.com/docs/grafana-cloud/ai-tools/mcp-servers/oss-mcp/developer/observability-metrics-and-tracing/"), source("MCP conformance framework", "https://github.com/modelcontextprotocol/conformance")],
    faq: [["How many products should be shortlisted?", "Usually two or three that can demonstrate the required boundary and privacy model. More options do not improve a vague evaluation."], ["When should a team build instead of buy?", "Build when you need unusual control and can own MCP semantics, storage, security, and support. Buy when maintained semantics and faster evidence outweigh that flexibility."]],
  },
};
